  out += line * WIDTH + line * PAD_SIZE + line / SMALL_HEIGHT * BIG_PAD_SIZE + (u32) get_local_id(0); // One pad every line + a big pad every SMALL_HEIGHT lines
  for (u32 i = 0; i < NW; ++i) { NTSTORE(out[i * G_W], u[i]); }
