  X2conjb(c, d);

  *pa = sub(cmul(a, c), cmul(cmul(b, d), t_squared));
  *pb = add(cmul(b, c), cmul(a, d));

  X2_conjb(*pa, *pb);
  *pa = SWAP_XY(*pa), *pb = SWAP_XY(*pb);
